CSS='''@font-face{font-family:Manrope;src:url("../landing/_shared/assets/manrope-regular.woff2") format("woff2");font-weight:400;font-display:swap}@font-face{font-family:Manrope;src:url("../landing/_shared/assets/manrope-semibold.woff2") format("woff2");font-weight:600 800;font-display:swap}@font-face{font-family:Marcellus;src:url("../landing/_shared/assets/marcellus.woff2") format("woff2");font-weight:400;font-display:swap}:root{--paper:#faf6f0;--plum:#3c183d;--muted:#625866;--line:#ddd4cb;--green:#476f65;--gold:#d7b86b;--sage:#e8eee8}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:28px}body{margin:0;background:var(--paper);color:var(--plum);font:16px/1.75 Manrope,Arial,sans-serif}a{color:inherit;text-underline-offset:4px;text-decoration-thickness:1px;overflow-wrap:anywhere}a:hover{color:var(--green)}a:focus-visible,summary:focus-visible{outline:3px solid var(--green);outline-offset:5px;border-radius:2px}button{font:inherit}.wrap{width:min(1160px,calc(100% - 64px));margin-inline:auto}.skip{position:absolute;top:-100px;left:16px;background:var(--paper);padding:12px;z-index:10}.skip:focus{top:10px}.header{border-bottom:1px solid var(--line)}.header-inner{min-height:102px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;align-items:center;gap:20px;text-decoration:none}.brand img{width:100px;height:auto;display:block}.brand span{font-size:13px;color:var(--muted);max-width:150px;line-height:1.4}.header nav{display:flex;gap:28px;align-items:center;font-size:14px}.header nav a{padding-block:12px}.review{background:var(--sage);border-bottom:1px solid #d3ddd3;font-size:13px;line-height:1.65}.review p{margin:0;padding:13px 0;color:#36574e}.review strong{font-weight:700}.hero{padding:64px 0 38px;max-width:880px}.eyebrow{font-size:12px;letter-spacing:.14em;font-weight:700;text-transform:uppercase;color:var(--green);margin:0 0 18px}.hero h1{font:400 clamp(36px,4.6vw,60px)/1.12 Marcellus,Georgia,serif;letter-spacing:-.025em;margin:0 0 22px;text-wrap:balance}.intro{font-size:19px;line-height:1.7;color:var(--muted);margin:0;max-width:750px}.date{font-size:12px;color:var(--muted);margin-top:20px}.summary{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:23px 0 23px 24px;margin:0 0 46px;display:grid;gap:9px;max-width:900px}.summary li{padding-left:5px;color:#514453}.body-layout{display:grid;grid-template-columns:230px minmax(0,740px);gap:72px;align-items:start;padding-bottom:76px}.contents{position:sticky;top:26px;font-size:13px}.contents strong{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--green)}.contents ol{list-style:none;padding:0;margin:16px 0}.contents li{border-bottom:1px solid var(--line)}.contents a{display:block;text-decoration:none;padding:10px 0;line-height:1.55}.contents a:hover{text-decoration:underline}.article section{padding:0 0 28px;margin:0 0 30px;border-bottom:1px solid var(--line);scroll-margin-top:28px}.article section:last-child{border-bottom:0;margin-bottom:0}.article h2{font:400 27px/1.3 Marcellus,Georgia,serif;margin:0 0 18px;text-wrap:balance}.section-number{font:600 12px Manrope,Arial,sans-serif;display:block;color:var(--green);margin-bottom:10px;letter-spacing:.06em}.article p{margin:0 0 17px;color:#514453}.article p:last-child{margin-bottom:0}.pending{padding:19px 22px;margin:22px 0;background:#f2ecdf;border-left:3px solid #ad8940}.pending strong{display:block;font-size:13px;margin-bottom:7px;color:#6a5022}.pending p{font-size:14px;line-height:1.75;color:#655437}.policy-list{display:grid;grid-template-columns:1fr 1fr;gap:0 40px;margin:12px 0 56px}.policy-card{display:block;text-decoration:none;padding:26px 0;border-top:1px solid var(--line)}.policy-card .n{font-size:12px;color:var(--green);letter-spacing:.1em}.policy-card h2{font:400 27px/1.3 Marcellus,Georgia,serif;margin:10px 0}.policy-card p{color:var(--muted);margin:0;font-size:14px;max-width:450px}.policy-card .arrow{display:block;color:var(--green);margin-top:15px;font-size:14px}.business{padding:34px;background:var(--sage);margin-bottom:44px}.business h2,.decisions h2{font:400 30px/1.25 Marcellus,Georgia,serif;margin:0 0 24px}.business dl{margin:0;display:grid;grid-template-columns:180px 1fr;gap:15px 26px}.business dt{font-size:13px;color:#51675e}.business dd{margin:0;overflow-wrap:anywhere;font-size:15px}.business small{display:block;margin-top:24px;color:var(--muted);font-size:12px}.decisions{max-width:820px;margin-bottom:64px}.decisions li{margin-bottom:12px;color:var(--muted)}.contact-strip{border-top:1px solid var(--line);padding:30px 0 46px;display:flex;justify-content:space-between;align-items:center;gap:24px}.contact-strip h2{font:400 28px/1.3 Marcellus,Georgia,serif;margin:0 0 8px}.contact-strip p{margin:0;color:var(--muted);font-size:14px}.contact-strip a{white-space:nowrap;font-weight:600;font-size:14px}.footer{background:var(--plum);color:var(--paper);padding:34px 0}.legal-nav{display:flex;flex-wrap:wrap;gap:6px 26px;font-size:13px}.legal-nav a{padding:8px 0;min-height:44px;display:inline-flex;align-items:center}.legal-nav a[aria-current=page]{color:#e5c98a}.footer p{font-size:12px;line-height:1.75;color:#e1d5df;margin:21px 0 0;max-width:800px}.footer a:hover{color:#e5c98a}.print{font-size:12px;margin-top:12px;color:var(--muted)}@media(max-width:800px){.body-layout{grid-template-columns:1fr;gap:34px}.contents{position:static;border-bottom:1px solid var(--line);padding-bottom:14px}.contents ol{columns:2;column-gap:28px}.contents li{break-inside:avoid}.hero{padding-top:44px}.brand span{display:none}.header nav{gap:20px}.business dl{grid-template-columns:130px 1fr}.body-layout{padding-bottom:40px}}@media(max-width:520px){.wrap{width:calc(100% - 36px)}.header-inner{min-height:85px;gap:14px}.brand img{width:84px}.header nav{gap:16px;font-size:12px}.header nav .optional{display:none}.review{font-size:12px}.hero{padding:36px 0 28px}.hero h1{font-size:36px}.intro{font-size:17px}.eyebrow{font-size:10px;letter-spacing:.1em}.summary{padding-left:19px;margin-bottom:30px;font-size:14px}.contents ol{columns:1}.contents a{padding:9px 0}.article h2{font-size:25px}.article p{font-size:16px;line-height:1.85}.article section{margin-bottom:24px;padding-bottom:24px}.pending{padding:16px}.policy-list{grid-template-columns:1fr;margin-bottom:32px}.business{padding:24px 20px}.business dl{grid-template-columns:1fr;gap:5px}.business dd{margin-bottom:15px}.business h2{font-size:27px}.contact-strip{display:block}.contact-strip a{display:inline-block;margin-top:18px}.footer{padding-bottom:38px}.legal-nav{gap:0 20px}.legal-nav a{font-size:12px}.decisions{margin-bottom:40px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.header,.review,.contents,.contact-strip,.footer,.print{display:none}.wrap{width:100%}.hero{padding-top:0}.body-layout{display:block}.article section,.business{break-inside:avoid}a{color:inherit}.hero h1{font-size:32px}.article h2{font-size:22px}}
'''

def legalnav(current):
    return '<nav class="legal-nav" aria-label="Legal policies">'+''.join(f'<a href="{BASE}/{slug}/"'+(' aria-current="page"' if slug==current else '')+f'>{label}</a>' for slug,label in NAV)+'</nav>'

def shell(slug,title,content):
    description=PAGES.get(slug,{}).get('intro','Terms, privacy, service boundaries and business contact details for Transformation with NNG.')
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#faf6f0"><title>{esc(title)} | Transformation with NNG</title><meta name="description" content="{esc(description,quote=True)}"><meta property="og:title" content="{esc(title,quote=True)} | NNG review"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:type" content="website"><link rel="icon" href="{BASE}/icon.svg"><link rel="stylesheet" href="../legal/policies.css?v=20261015"><link rel="preload" href="{BASE}/landing/_shared/assets/manrope-regular.woff2" as="font" type="font/woff2" crossorigin></head>
<body><a href="#main" class="skip">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="brand" href="{BASE}/" aria-label="NNG homepage"><img src="{BASE}/images/nng-logo-200.webp" alt="Transformation with NNG" width="100" height="53"><span>Mind. Direction.<br>Alignment.</span></a><nav aria-label="Website navigation"><a class="optional" href="{BASE}/services/">Services</a><a href="{BASE}/contact/">Contact</a><a href="{BASE}/legal/">Legal</a></nav></div></header><aside class="review" aria-label="Review status"><div class="wrap"><p><strong>Public staging review · {DATE}.</strong> Proposed policies for Team NNG review. Pending items are marked. Effective date: awaiting approval.</p></div></aside><main id="main" class="wrap">{content}<div class="contact-strip"><div><h2>General enquiries</h2><p>Ask the team about a consultation or order.</p></div><a href="mailto:enquiry@nngarg.com">enquiry@nngarg.com ↗</a></div><div class="contact-strip" aria-label="Grievance contact"><div><h2>Grievances & complaints</h2><p>Email only. Please include your booking or order reference, if available.</p></div><a href="mailto:enquire@nngarg.com">enquire@nngarg.com ↗</a></div></main><footer class="footer"><div class="wrap">{legalnav(slug)}<p>© 2026 Transformation with NNG. Guidance is personal and spiritual. Read the service boundaries before booking.<br>Review draft dated {DATE}; not a production release.</p></div></footer></body></html>'''

def build():
    OUT.mkdir(exist_ok=True)
    for slug,page in PAGES.items():
        hero=f'<div class="hero"><p class="eyebrow">{page["label"]}</p><h1>{page["title"]}</h1><p class="intro">{page["intro"]}</p><p class="date">Review version · {DATE} · Effective date pending</p></div>'
        summary='<ul class="summary">'+''.join(f'<li>{x}</li>' for x in page['summary'])+'</ul>'
        toc='<aside class="contents"><strong>On this page</strong><ol>'+''.join(f'<li><a href="#{key}">{i:02d}. {title}</a></li>' for i,(key,title,_) in enumerate(page['sections'],1))+'</ol></aside>'
        article='<article class="article">'+''.join(f'<section id="{key}" aria-labelledby="{key}-title"><span class="section-number">{i:02d}</span><h2 id="{key}-title">{title}</h2>{body}</section>' for i,(key,title,body) in enumerate(page['sections'],1))+'</article>'
        dest=OUT/slug/'index.html';dest.parent.mkdir(exist_ok=True)
        dest.write_text(shell(slug,page['title'],hero+summary+'<div class="body-layout">'+toc+article+'</div>'))
    cards=''.join(f'<a class="policy-card" href="{BASE}/{slug}/"><span class="n">0{i}</span><h2>{page["title"]}</h2><p>{page["intro"]}</p><span class="arrow">Read the review draft ↗</span></a>' for i,(slug,page) in enumerate(PAGES.items(),1))
    business='<section class="business" id="business"><h2>Business & contact details</h2><dl>'+''.join(f'<dt>{k}</dt><dd>{v}</dd>' for k,v in [
      ('Trade name',BUSINESS['trade']),('Legal name',BUSINESS['legal']),('Business type',BUSINESS['constitution']),('GSTIN',BUSINESS['gstin']),('Principal business address',BUSINESS['address']),('General enquiries','<a href="mailto:enquiry@nngarg.com">enquiry@nngarg.com</a>'),('General enquiry phone','<a href="tel:+919205511101">+91 92055 11101</a>'),('Grievances (email only)','<a href="mailto:enquire@nngarg.com">enquire@nngarg.com</a>'),('Payment methods',BUSINESS['payment_methods']),('Bill / invoice',BUSINESS['billing']),('Grievance / privacy officer','Awaiting NNG confirmation')])+'</dl><small>Business identity transcribed from the GST registration certificate supplied by NNG, issued 30 August 2026. General contact channels match the staging site; the email-only grievance channel, payment methods and billing responsibility were confirmed by Aryan on 15 October 2026. This is not an independent live GST-status verification.</small></section>'
    pending='<section class="decisions"><h2>Before these policies take effect</h2><p>The review copy is complete enough to assess the proposed approach. These operational decisions still need Team NNG confirmation:</p><ul><li>Designated grievance/privacy officer and complaint escalation process.</li><li>Consultation rescheduling, no-show, cancellation and refund rules.</li><li>Programme inclusions, contact hours, pause and early-exit terms.</li><li>Product seller, returns, shipping and payment arrangements.</li><li>Actual data providers, access controls, retention periods and permissions.</li></ul><p>There is no separate universal requirement for a page titled “Legal”. This page brings the business details and policies together. The relevant disclosures and operating processes are what matter.</p></section>'
    content='<div class="hero"><p class="eyebrow">Clear information, before you decide.</p><h1>Legal & contact</h1><p class="intro">Understand your consultation, your information and your order. Everything in one place.</p><p class="date">Public review draft · '+DATE+'</p></div><div class="policy-list">'+cards+'</div>'+business+pending
    dest=OUT/'legal';dest.mkdir(exist_ok=True);(dest/'index.html').write_text(shell('legal','Legal & contact',content));(dest/'policies.css').write_text(CSS)
    questions='# Team NNG | Policy decisions to confirm\n\nReply under each question. These answers will complete the public policy drafts.\n\nBusiness identity has been taken from the supplied GST certificate; the grievance officer is not stated there.\n\n'+''.join(f'## {i}. {topic}\n\n{q}\n\n**Team NNG answer:**\n\n' for i,(topic,q) in enumerate(QUESTIONS,1))
    (ROOT/'Team_NNG_Policy_Questions.md').write_text(questions)
    print('Built',len(PAGES)+1,'pages; questions',len(QUESTIONS),'total page bytes',sum(p.stat().st_size for p in OUT.rglob('*') if p.is_file()))

if __name__=='__main__': build()
